<div x-data="{ token: null, copiado: false, errorCopia: false, limpiar() { this.token = null; }, async copiar() { try { await navigator.clipboard.writeText(this.token); this.limpiar(); this.copiado = true; } catch { this.errorCopia = true; } } }"
    @api-token-created.window="token = $event.detail.token; copiado = false; errorCopia = false"
    @api-token-dismissed.window="limpiar()"
    @keydown.escape.window="limpiar()"
    @pagehide.window="limpiar()"
    class="mx-auto max-w-7xl space-y-6 p-6"><div><p class="text-xs font-semibold uppercase text-blue-700">Configuración</p><h1 class="text-2xl font-bold text-gray-900">Tokens de acceso API</h1><p class="text-sm text-gray-500">Administre tokens sin almacenar secretos completos.</p></div><template x-if="token"><div role="dialog" aria-label="Token generado" class="rounded-lg border border-amber-300 bg-amber-50 p-4"><b>Token generado</b><p>Copie este token ahora; no se puede recuperar después.</p><button type="button" title="Copiar token" aria-label="Copiar token" @click="copiar()" class="rounded-md border border-amber-500 bg-white px-3 py-2 text-xl text-amber-700">⧉<span class="sr-only">Copiar token</span></button><button type="button" @click="limpiar()">Cerrar</button><p x-show="errorCopia" role="alert">No se pudo copiar. Intente nuevamente antes de cerrar.</p></div></template><p x-show="copiado" role="status">Token copiado.</p><button @click="limpiar()" wire:click="nuevo" class="rounded-md bg-blue-700 px-4 py-2 text-sm font-semibold text-white">Crear token</button>@if($showForm)<form wire:submit.prevent="guardar" class="rounded-lg border bg-white p-6 shadow space-y-4"><h2 class="text-lg font-semibold">{{ $editingId ? 'Editar token' : 'Crear token' }}</h2><label class="block text-sm font-medium text-gray-700">Nombre del token<input wire:model="nombre" placeholder="Nombre del token" class="mt-1 w-full rounded-md border-gray-300"></label>@error('nombre')<span class="text-sm text-red-600">{{ $message }}</span>@enderror<label class="block text-sm font-medium text-gray-700">Fecha de expiración del token (opcional)<input type="date" wire:model="expira_en" class="mt-1 rounded-md border-gray-300"><span class="mt-1 block text-xs text-gray-500">Si la deja vacía, el token no expira automáticamente.</span></label><div><p class="mb-2 font-semibold">Alcances API</p>@foreach($catalogoScopes as $scope)<label class="mr-5"><input type="checkbox" wire:model="scopes" value="{{ $scope->id }}"> {{ $scope->nombre }}</label>@endforeach</div><button class="rounded-md bg-green-700 px-4 py-2 text-white">Guardar</button><button type="button" wire:click="cerrar" @click="limpiar()">Cancelar</button></form>@endif<div class="overflow-x-auto rounded-lg border bg-white"><table class="min-w-full text-sm"><thead class="bg-gray-50"><tr><th class="p-3 text-left">Nombre</th><th class="p-3 text-left">Prefijo</th><th class="p-3 text-left">Estado</th><th class="p-3 text-left">Alcances</th><th class="p-3 text-left">Fechas</th><th class="p-3"></th></tr></thead><tbody>@forelse($tokens as $token)<tr class="border-t"><td class="p-3">{{ $token->nombre }}</td><td class="p-3 font-mono">{{ $token->prefijo }}…</td><td class="p-3">{{ $token->revocado_en ? 'Revocado' : ($token->expira_en?->isPast() ? 'Expirado' : 'Activo') }}</td><td class="p-3">{{ $token->scopes->pluck('nombre')->join(', ') ?: 'Sin alcances' }}</td><td class="p-3">Creado {{ $token->created_at?->format('d/m/Y') }}<br>Expira {{ $token->expira_en?->format('d/m/Y') ?: 'Sin expiración' }}<br>Último uso {{ $token->ultimo_uso_en?->format('d/m/Y H:i') ?: 'Nunca' }}</td><td class="space-x-3 p-3"><button @click="limpiar()" wire:click="editar({{ $token->id }})" class="text-blue-700">Editar</button>@if(!$token->revocado_en)<button @click="limpiar()" wire:click="revocar({{ $token->id }})" class="text-red-700">Revocar</button>@endif</td></tr>@empty<tr><td colspan="6" class="p-6 text-center text-gray-500">No hay tokens.</td></tr>@endforelse</tbody></table></div></div>
